export function imageSet(slug) {
  const item = media[slug];
  if (!item) throw new Error(`Unknown image: ${slug}`);
  const set = (ext) =>
    item.widths
      .map((w) => `/images/deeva/${slug}-${w}.${ext} ${Math.min(w, item.w)}w`)
      .join(", ");
  return {
    ...item,
    avif: set("avif"),
    webp: set("webp"),
    src: `/images/deeva/${slug}-${item.widths[Math.min(1, item.widths.length - 1)]}.webp`,
  };
}
